{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile standing on a small patch of dirt and sparse grass. It has the overall size, proportions, fur and posture of a brown bear with dense brown fur that is lighter tan on the belly and darker on the limbs, and a thick ruff of fur around the neck and shoulders. The head is bear-like with an elongated muzzle, black nose, brown eyes and a calm expression. Arising from the center of the forehead is a single long, glossy black, sickle-shaped horn that curves up and forward with small thorn-like points along its edge. The entire dorsal surface from the shoulders to the rump is covered by a series of glossy dark brown to black segmented plates with tan-brown sutures between them, plus a large shield-like plate over the shoulders and neck with a fringe of small spikes along its lower edge, and additional matching plates over the hips and as banded rings around the upper forelegs and hind legs. Four sturdy furry legs support the body and end in clawed paws, and a small furry tail is visible at the rear beneath the plating.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with brown fur, elongated muzzle, black nose with nostrils, small brown eyes, and a closed mouth, facing to the right at the front of the body"
    ,
      "where": "at the anterior end of the body, attached to the furry neck ruff"
    },
    {
      "part": "horns",
      "looks_like": "single long, glossy black, strongly curved sickle-shaped horn with a pointed tip and several small sharp projections along the inner curve and base, smooth and shiny like beetle chitin",
      "where": "arising from the midline of the forehead on top of the head, curving upward and forward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry ears covered in brown fur, with the right ear more visible in profile",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy ruff of longer brown fur with layered folds",
      "where": "around the neck and front of the shoulders, surrounding the base of the large shoulder plate"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar legs covered in dense brown fur, darker brown on the lower portions",
      "where": "two forelegs under the chest/shoulder region and two hind legs under the hip region, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with brown fur on top and five dark claws/toes visible on each, flat on the ground",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, rounded furry tail covered in brown fur",
      "where": "at the posterior end of the body, protruding from beneath the rear dorsal plates on the left side of the image"
    },
    {
      "part": "plates",
      "looks_like": "multiple glossy, hard, dark brown to black chitinous plates with tan-brown ridged sutures between them and small surface scratches; includes five large segmented dorsal plates over the back, a large smooth shield over the shoulders with a spiky fringed lower margin and a row of circular pits along the side, a paired hip shield over the hindquarters, and segmented band-like rings encircling the upper forelegs and hind legs",
      "where": "covering the dorsal midline from shoulders to rump, over the shoulders and neck, over the outer hips, and as bands around the upper portions of all four legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
